cd /workspace && python3 - <<'PY'
import subprocess, json, base64, hmac, hashlib, os, time
bin='/workspace/artifacts/target/jwt-verify'
secret='s3cr3t'

def b64url(data): return base64.urlsafe_b64encode(data).rstrip(b'=').decode()
def token(payload, key=secret):
    header={'alg':'HS256','typ':'JWT'}
    e=b64url(json.dumps(header,separators=(',',':')).encode())+'.'+b64url(json.dumps(payload,separators=(',',':')).encode())
    sig=hmac.new(key.encode(),e.encode(),hashlib.sha256).digest()
    return e+'.'+b64url(sig)
def run(t):
    p=subprocess.run([bin,'--token',t,'--key',secret],capture_output=True,text=True,timeout=10)
    return p.returncode,p.stdout.strip(),p.stderr.strip()
payloads=[{}, {'foo':'bar'}, {'role':'admin'}, {'role':'user'}, {'iss':'x'}, {'sub':'x'}, {'aud':'x'}, {'exp':9999999999}, {'nbf':1}, {'iat':1}, {'scope':'admin'}, {'admin':True}]
for pl in payloads:
    rc,out,err=run(token(pl))
    print(json.dumps(pl), rc, out, err)
PY

